function paraNumero(valor) {
  if (typeof valor === 'number') {
    return Number.isFinite(valor) ? valor : null;
  }
  if (typeof valor !== 'string') {
    return null;
  }

  const limpo = valor.trim().replace(/\s/g, '').replace(',', '.');
  if (limpo === '') {
    return null;
  }

  const numero = Number(limpo);
  return Number.isFinite(numero) ? numero : null;
}

console.log(paraNumero('1 234,56')); // 1234.56
console.log(paraNumero(' 42 '));     // 42
console.log(paraNumero('-3,5'));     // -3.5
console.log(paraNumero(7.5));        // 7.5
console.log(paraNumero('42px'));     // null
console.log(paraNumero(''));         // null
console.log(paraNumero(null));       // null
console.log(paraNumero(true));       // null
console.log(paraNumero([]));         // null
console.log(paraNumero(NaN));        // null
console.log(paraNumero(Infinity));   // null

const TAXA_IVA = 0.23;

function euroParaCentimos(euros) {
  const centimos = Math.round(euros * 100);
  if (!Number.isSafeInteger(centimos)) {
    throw new RangeError('valor fora do intervalo de inteiros seguros');
  }
  return centimos;
}

function formatarEuros(centimos) {
  return `${(centimos / 100).toFixed(2)} EUR`;
}

function calcularCarrinho(itens) {
  const subtotalCentimos = itens.reduce(
    (total, item) => total + euroParaCentimos(item.preco) * item.quantidade,
    0
  );
  const ivaCentimos = Math.round(subtotalCentimos * TAXA_IVA);
  const totalCentimos = subtotalCentimos + ivaCentimos;

  return {
    subtotalCentimos,
    ivaCentimos,
    totalCentimos,
    totalFormatado: formatarEuros(totalCentimos)
  };
}

const carrinho = [
  { nome: 'Teclado', preco: 19.99, quantidade: 2 },
  { nome: 'Rato', preco: 9.95, quantidade: 1 },
  { nome: 'Cabo', preco: 0.1, quantidade: 3 }
];

console.log(calcularCarrinho(carrinho));
// { subtotalCentimos: 5023, ivaCentimos: 1155,
//   totalCentimos: 6178, totalFormatado: '61.78 EUR' }

